235:   // Get block ID at (bx, by) in a zone, including connected neighbor zones in the 3-block border!
236:   getBlockAt(zone, bx, by) {
237:     if (bx >= 0 && bx < zone.width && by >= 0 && by < zone.height) {
238:       return zone.blockBytes[by * zone.width + bx];
239:     }
240:     const conns = zone.connections || {};
241:     // Check North connection (by in -3..-1)
242:     if (by < 0 && by >= -3 && conns.north) {
243:       const target = this.zonesByConst[conns.north.targetConst];
244:       if (target) {
245:         const tx = bx - conns.north.offset;
246:         const ty = target.height + by;
247:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
248:           return target.blockBytes[ty * target.width + tx];
249:         }
250:       }
251:     }
252:     // Check South connection (by in height..height+2)
253:     if (by >= zone.height && by < zone.height + 3 && conns.south) {
254:       const target = this.zonesByConst[conns.south.targetConst];
255:       if (target) {
256:         const tx = bx - conns.south.offset;
257:         const ty = by - zone.height;
258:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
259:           return target.blockBytes[ty * target.width + tx];
260:         }
261:       }
262:     }
263:     // Check West connection (bx in -3..-1)
264:     if (bx < 0 && bx >= -3 && conns.west) {
265:       const target = this.zonesByConst[conns.west.targetConst];
266:       if (target) {
267:         const tx = target.width + bx;
268:         const ty = by - conns.west.offset;
269:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
270:           return target.blockBytes[ty * target.width + tx];
271:         }
272:       }
273:     }
274:     // Check East connection (bx in width..width+2)
275:     if (bx >= zone.width && bx < zone.width + 3 && conns.east) {
276:       const target = this.zonesByConst[conns.east.targetConst];
277:       if (target) {
278:         const tx = bx - zone.width;
279:         const ty = by - conns.east.offset;
280:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
281:           return target.blockBytes[ty * target.width + tx];
282:         }
283:       }
284:     }
285:     return zone.borderBlock;
286:   }
