496:   // Render an entire zone segment (width*32 x height*32 pixels) onto a Canvas
497:   renderFullZone(
498:     canvas,
499:     zone,
500:     options = {}
501:   ) {
502:     const {
503:       showBorder = false,
504:       showEntities = true,
505:       showWarps = false,
506:       showGrid = false,
507:       showHiddenObjects = false,
508:       playerState = null,
509:       pikachuState = null,
510:       npcStates = null,
511:     } = options;
512: 
513:     const borderBlocks = showBorder ? 1 : 0;
514:     const totalBlocksW = zone.width + borderBlocks * 2;
515:     const totalBlocksH = zone.height + borderBlocks * 2;
516:     const pxW = totalBlocksW * 32;
517:     const pxH = totalBlocksH * 32;
518: 
519:     if (canvas.width !== pxW || canvas.height !== pxH) {
520:       canvas.width = pxW;
521:       canvas.height = pxH;
522:     }
523: 
524:     const ctx = canvas.getContext("2d");
525:     const imgData = ctx.createImageData(pxW, pxH);
526:     const buf = imgData.data;
527: 
528:     const ts = this.tilesetsByConst[zone.tileset];
529:     const bst = this.bstData[ts.bstKey];
530:     const pal = this.getPaletteColors(zone.palette);
531: 
532:     for (let by = -borderBlocks; by < zone.height + borderBlocks; by++) {
533:       for (let bx = -borderBlocks; bx < zone.width + borderBlocks; bx++) {
534:         const blockId = this.getBlockAt(zone, bx, by);
535:         const destBlockX = (bx + borderBlocks) * 32;
536:         const destBlockY = (by + borderBlocks) * 32;
537:         for (let ty = 0; ty < 4; ty++) {
538:           for (let tx = 0; tx < 4; tx++) {
539:             const tileId = bst[blockId * 16 + ty * 4 + tx] || 0;
540:             this.drawTile8x8(
541:               buf,
542:               pxW,
543:               pxH,
544:               destBlockX + tx * 8,
545:               destBlockY + ty * 8,
546:               ts,
547:               tileId,
548:               pal
549:             );
550:           }
551:         }
552:       }
553:     }
554: 
555:     const originPx = borderBlocks * 32;
556: 
557:     if (showEntities) {
558:       // Draw zone objects (NPCs, items, trainers)
559:       const list = npcStates || zone.objects;
560:       for (const obj of list) {
561:         if (!obj.defaultVisible && !showHiddenObjects) continue;
562:         if (obj.collected) continue;
563:         const sprKey = this.spriteConstToKey[obj.sprite] || "red";
564:         const ox = originPx + Math.round((obj.renderX ?? obj.x) * 16);
565:         const oy = originPx + Math.round((obj.renderY ?? obj.y) * 16) - 4;
566:         const dir =
567:           obj.facing ||
568:           (obj.dir === "UP" || obj.dir === "DOWN" || obj.dir === "LEFT" || obj.dir === "RIGHT"
569:             ? obj.dir
570:             : "DOWN");
571:         const onGrass =
572:           this.getCollisionTileAtStep(
573:             zone,
574:             Math.round(obj.renderX ?? obj.x),
575:             Math.round(obj.renderY ?? obj.y)
576:           ) === ts.grassTile;
577:         this.drawSprite16x16(
578:           buf,
579:           pxW,
580:           pxH,
581:           ox,
582:           oy,
583:           sprKey,
584:           dir,
585:           Boolean(obj.isWalking),
586:           Boolean(obj.stepParity),
587:           pal,
588:           onGrass
589:         );
590:       }
591: 
592:       // Draw following Pikachu & Player if in this zone (ShouldPikachuSpawn: only when walking!)
