233: export function buildMonInstance(speciesKey, level = 10, customMoveIds = null) {
234:   const cleanKey = String(speciesKey || "PIKACHU").toUpperCase();
235:   const base = POKEYELLOW_DATA.battle?.pokemonStats?.[cleanKey] ||
236:     POKEYELLOW_DATA.battle?.pokemonStats?.PIKACHU || {
237:       species: cleanKey,
238:       hp: 45,
239:       atk: 55,
240:       def: 45,
241:       spd: 60,
242:       spc: 50,
243:       types: ["NORMAL"],
244:       catchRate: 190,
245:       baseExp: 64,
246:       baseMoves: ["TACKLE"],
247:       learnset: [],
248:     };
249: 
250:   const lv = Math.max(1, Math.min(100, Number(level) || 10));
251:   const maxHp = Math.floor(((base.hp + 15) * 2 * lv) / 100) + lv + 10;
252:   const atk = Math.floor(((base.atk + 15) * 2 * lv) / 100) + 5;
253:   const def = Math.floor(((base.def + 15) * 2 * lv) / 100) + 5;
254:   const spd = Math.floor(((base.spd + 15) * 2 * lv) / 100) + 5;
255:   const spc = Math.floor(((base.spc + 15) * 2 * lv) / 100) + 5;
256: 
257:   let moveIds = [];
258:   if (Array.isArray(customMoveIds) && customMoveIds.length > 0) {
259:     moveIds = customMoveIds.slice(0, 4);
260:   } else {
261:     const known = [...(base.baseMoves || ["TACKLE"])];
262:     for (const [learnLv, mId] of base.learnset || []) {
263:       if (learnLv <= lv && !known.includes(mId)) {
264:         known.push(mId);
265:       }
266:     }
267:     moveIds = known.slice(-4);
268:   }
269:   if (moveIds.length === 0) moveIds = ["TACKLE"];
270: 
271:   return {
272:     species: cleanKey,
273:     nickname: cleanKey.replace(/_/g, " "),
274:     level: lv,
275:     hp: maxHp,
276:     maxHp,
277:     atk,
278:     def,
279:     spd,
280:     spc,
281:     types: base.types || ["NORMAL"],
282:     catchRate: base.catchRate ?? 120,
283:     baseExp: base.baseExp ?? 64,
284:     status: "OK", // "OK" | "PAR" | "PSN" | "SLP" | "BRN" | "FRZ"
285:     moves: moveIds.map((mId) => getMoveObj(mId)),
286:   };
287: }
