453: function findDefaultSpawn(zone, spawnWarpIndex = null) {
454:   if (spawnWarpIndex !== null && zone.warps[spawnWarpIndex]) {
455:     const w = zone.warps[spawnWarpIndex];
456:     const ts = engine.tilesetsByConst[zone.tileset];
457:     const tileAtWarp = engine.getCollisionTileAtStep(zone, w.x, w.y);
458:     // If emerging onto an outdoor door tile, step 1 tile down if passable
459:     if (
460:       zone.romId < 0x25 &&
461:       ts.doorSet.has(tileAtWarp) &&
462:       w.y + 1 < zone.height * 2
463:     ) {
464:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
465:     }
466:     return { x: w.x, y: w.y, dir: "DOWN" };
467:   }
468: 
469:   // For Pallet Town default spawn right between Red's House and Oak's Lab
470:   if (zone.constName === "PALLET_TOWN") {
471:     return { x: 5, y: 6, dir: "DOWN" };
472:   }
473: 
474:   // If the zone has warps, spawn near the first warp or center
475:   if (zone.warps.length > 0) {
476:     const w = zone.warps[0];
477:     if (zone.romId < 0x25 && w.y + 1 < zone.height * 2) {
478:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
479:     }
480:     if (w.y > 0 && engine.isStepPassable(zone, w.x, w.y, w.x, w.y - 1)) {
481:       return { x: w.x, y: w.y - 1, dir: "UP" };
482:     }
483:     return { x: w.x, y: w.y, dir: "DOWN" };
484:   }
485: 
486:   // Otherwise find nearest passable tile to center
487:   const cx = Math.floor(zone.width);
488:   const cy = Math.floor(zone.height);
489:   const ts = engine.tilesetsByConst[zone.tileset];
490:   for (let r = 0; r < Math.max(zone.width, zone.height) * 2; r++) {
491:     for (let dy = -r; dy <= r; dy++) {
492:       for (let dx = -r; dx <= r; dx++) {
493:         const sx = cx + dx;
494:         const sy = cy + dy;
495:         if (sx >= 0 && sx < zone.width * 2 && sy >= 0 && sy < zone.height * 2) {
496:           const tid = engine.getCollisionTileAtStep(zone, sx, sy);
497:           if (ts.passableSet.has(tid)) {
498:             return { x: sx, y: sy, dir: "DOWN" };
499:           }
500:         }
501:       }
502:     }
503:   }
504:   return { x: cx, y: cy, dir: "DOWN" };
505: }
