694: function isWaterTile(zone, tileId) {
695:   return (
696:     (zone.tileset === "OVERWORLD" ||
697:       zone.tileset === "FOREST" ||
698:       zone.tileset === "PLATEAU" ||
699:       zone.tileset === "CAVERN" ||
700:       zone.tileset === "SHIP_PORT") &&
701:     (tileId === 0x14 || tileId === 0x32 || tileId === 0x48)
702:   );
