705: function attemptStep(dir) {
706:   if (state.dialogue || state.battle) return;
707:   if (state.player.moveAnim) return;
708: 
709:   const zone = state.currentZone;
710:   state.player.dir = dir;
711: 
712:   const dx = dir === "LEFT" ? -1 : dir === "RIGHT" ? 1 : 0;
713:   const dy = dir === "UP" ? -1 : dir === "DOWN" ? 1 : 0;
714:   const targetX = state.player.x + dx;
715:   const targetY = state.player.y + dy;
716: 
717:   // 1. Check if standing on a warp tile at the edge of an indoor room and pressing outward
718:   const standingWarp = checkWarpAtStep(zone, state.player.x, state.player.y);
719:   if (standingWarp) {
720:     const ts = engine.tilesetsByConst[zone.tileset];
721:     const curTile = engine.getCollisionTileAtStep(
722:       zone,
723:       state.player.x,
724:       state.player.y
725:     );
726:     const pushingOut =
727:       (dir === "DOWN" && state.player.y === zone.height * 2 - 1) ||
728:       (dir === "UP" && state.player.y === 0) ||
729:       (dir === "LEFT" && state.player.x === 0) ||
730:       (dir === "RIGHT" && state.player.x === zone.width * 2 - 1) ||
731:       (zone.romId >= 0x25 && dir === "DOWN" && ts.warpSet.has(curTile));
732:     if (pushingOut) {
733:       const { destConst, destWarpIdx } = resolveWarpDestination(
734:         zone,
735:         standingWarp.warp
736:       );
737:       audio.playSfx("warp");
738:       loadZone(destConst, {
739:         warpIndex: destWarpIdx,
740:         fromOutdoorWarpIndex: standingWarp.warpIdx,
741:       });
742:       return;
743:     }
744:   }
745: 
746:   // 2. Check map border connections (North / South / West / East seamless transition!)
747:   const conns = zone.connections || {};
748:   if (targetY < 0 && conns.north) {
749:     const targetZone = engine.zonesByConst[conns.north.targetConst];
750:     if (targetZone) {
751:       const newX = targetX - conns.north.offset * 2;
752:       const newY = targetZone.height * 2 - 1;
753:       if (newX >= 0 && newX < targetZone.width * 2) {
754:         loadZone(targetZone, { x: newX, y: newY, dir: "UP" });
755:         return;
756:       }
757:     }
758:   }
759:   if (targetY >= zone.height * 2 && conns.south) {
760:     const targetZone = engine.zonesByConst[conns.south.targetConst];
761:     if (targetZone) {
762:       const newX = targetX - conns.south.offset * 2;
763:       const newY = 0;
764:       if (newX >= 0 && newX < targetZone.width * 2) {
765:         loadZone(targetZone, { x: newX, y: newY, dir: "DOWN" });
766:         return;
767:       }
768:     }
769:   }
770:   if (targetX < 0 && conns.west) {
771:     const targetZone = engine.zonesByConst[conns.west.targetConst];
772:     if (targetZone) {
773:       const newX = targetZone.width * 2 - 1;
774:       const newY = targetY - conns.west.offset * 2;
775:       if (newY >= 0 && newY < targetZone.height * 2) {
776:         loadZone(targetZone, { x: newX, y: newY, dir: "LEFT" });
777:         return;
778:       }
779:     }
780:   }
781:   if (targetX >= zone.width * 2 && conns.east) {
782:     const targetZone = engine.zonesByConst[conns.east.targetConst];
783:     if (targetZone) {
784:       const newX = 0;
785:       const newY = targetY - conns.east.offset * 2;
786:       if (newY >= 0 && newY < targetZone.height * 2) {
787:         loadZone(targetZone, { x: newX, y: newY, dir: "RIGHT" });
788:         return;
789:       }
790:     }
791:   }
792: 
793:   // Bounds check inside current zone
794:   if (
795:     targetX < 0 ||
796:     targetX >= zone.width * 2 ||
797:     targetY < 0 ||
798:     targetY >= zone.height * 2
799:   ) {
800:     audio.playSfx("bump");
801:     return;
802:   }
803: 
804:   // 3. Check one-way ledge jump!
805:   if (
806:     !state.noClip &&
807:     engine.canJumpLedge(zone, state.player.x, state.player.y, dir)
808:   ) {
809:     const landX = state.player.x + dx * 2;
810:     const landY = state.player.y + dy * 2;
811:     if (
812:       landX >= 0 &&
813:       landX < zone.width * 2 &&
814:       landY >= 0 &&
815:       landY < zone.height * 2
816:     ) {
817:       audio.playSfx("ledge");
818:       startPlayerMove(landX, landY, dir, 260, true);
819:       return;
820:     }
821:   }
822: 
823:   // 4. Check NPC collision
824:   if (!state.noClip) {
825:     for (const npc of state.npcs) {
826:       if (!npc.defaultVisible && !state.showHiddenObjects) continue;
827:       if (npc.collected) continue;
828:       if (npc.x === targetX && npc.y === targetY) {
829:         audio.playSfx("bump");
830:         return;
831:       }
832:     }
833:   }
834: 
835:   // 5. Check tile passability or water surfing
836:   const targetTile = engine.getCollisionTileAtStep(zone, targetX, targetY);
837:   const water = isWaterTile(zone, targetTile);
838:   const passable =
839:     state.noClip ||
840:     engine.isStepPassable(zone, state.player.x, state.player.y, targetX, targetY) ||
841:     (water && (state.player.mode === "surf" || state.autoSurf));
842: 
843:   // Also allow stepping directly onto a warp_event coordinate (e.g. stairs/doors)
844:   const targetWarp = checkWarpAtStep(zone, targetX, targetY);
845: 
846:   if (!passable && !targetWarp) {
847:     audio.playSfx("bump");
848:     return;
849:   }
850: 
851:   const wasSurfing = state.player.mode === "surf";
852:   if (water && state.player.mode !== "surf") {
853:     // Entering water (ItemUseSurfboard in engine/items/item_effects.asm:715):
854:     // wWalkBikeSurfState = 2 -> ShouldPikachuSpawn hides following Pikachu!
855:     state.player.mode = "surf";
856:     state.pikachu.spawnDelayed = false;
857:     syncPikachuOverworldState();
858:   } else if (!water && wasSurfing) {
859:     // Stepping from water onto land (ItemUseSurfboard.stopSurfing in engine/items/item_effects.asm:743):
860:     // wWalkBikeSurfState = 0 with PIKACHU_SPAWN_DELAYED so Pikachu does not spawn on the water tile behind Red!
861:     state.player.mode = "walk";
862:     state.pikachu.spawnDelayed = true;
863:     state.pikachu.x = targetX;
864:     state.pikachu.y = targetY;
865:     state.pikachu.renderX = targetX;
866:     state.pikachu.renderY = targetY;
867:     syncPikachuOverworldState();
868:   } else if (!water && state.player.mode === "walk" && state.pikachu.spawnDelayed) {
869:     // Next walking step on dry land: clear PIKACHU_SPAWN_DELAYED so Pikachu emerges at Red's land tile!
870:     state.pikachu.spawnDelayed = false;
871:     state.pikachu.x = state.player.x;
872:     state.pikachu.y = state.player.y;
873:     state.pikachu.renderX = state.player.x;
874:     state.pikachu.renderY = state.player.y;
875:     syncPikachuOverworldState();
876:   }
877: 
878:   const dur = state.player.mode === "bike" ? 105 : 165;
879:   startPlayerMove(targetX, targetY, dir, dur, false);
880: }
