882: function startPlayerMove(destX, destY, dir, durationMs, isLedgeJump = false) {
883:   const prevPlayerX = state.player.x;
884:   const prevPlayerY = state.player.y;
885: 
886:   state.player.walking = true;
887:   state.player.stepParity = !state.player.stepParity;
888:   state.player.moveAnim = {
889:     fromX: state.player.x,
890:     fromY: state.player.y,
891:     toX: destX,
892:     toY: destY,
893:     startTime: performance.now(),
894:     duration: durationMs,
895:     isLedgeJump,
896:   };
897: 
898:   // Move Pikachu to Red's previous step
899:   if (state.pikachu.visible) {
900:     const pdx = prevPlayerX - state.pikachu.x;
901:     const pdy = prevPlayerY - state.pikachu.y;
902:     let pdir = dir;
903:     if (Math.abs(pdx) + Math.abs(pdy) > 0) {
904:       if (Math.abs(pdx) >= Math.abs(pdy)) {
905:         pdir = pdx > 0 ? "RIGHT" : "LEFT";
906:       } else {
907:         pdir = pdy > 0 ? "DOWN" : "UP";
908:       }
909:     }
910:     state.pikachu.dir = pdir;
911:     state.pikachu.walking = true;
912:     state.pikachu.stepParity = !state.pikachu.stepParity;
913:     state.pikachu.moveAnim = {
914:       fromX: state.pikachu.x,
915:       fromY: state.pikachu.y,
916:       toX: prevPlayerX,
917:       toY: prevPlayerY,
918:       startTime: performance.now(),
919:       duration: durationMs,
920:     };
921:   }
922: }
