1109: export function triggerNpcDialogue(npc, zone = state.currentZone) {
1110:   if (!npc || !zone) return;
1111:   // Turn NPC toward player (unless inanimate item ball / map book)
1112:   if (
1113:     npc.kind !== "item" &&
1114:     npc.sprite !== "SPRITE_POKE_BALL" &&
1115:     npc.sprite !== "SPRITE_POKEDEX" &&
1116:     npc.sprite !== "SPRITE_BOOK_MAP_DEX"
1117:   ) {
1118:     const opp = { UP: "DOWN", DOWN: "UP", LEFT: "RIGHT", RIGHT: "LEFT" };
1119:     npc.facing = opp[state.player.dir] || "DOWN";
1120:   }
1121: 
1122:   // Only actual Poké Ball ground items disappear when picked up; NPCs NEVER disappear!
1123:   if (npc.kind === "item" && npc.sprite === "SPRITE_POKE_BALL") {
1124:     npc.collected = true;
