2191:       audio.playSfx("blip");
2192:       renderBattleModal();
2193:     } else if (input === "SELECT") {
2194:       // Matches SwapMovesInMenu in engine/battle/core.asm (lines 2926-3008)
2195:       audio.playSfx("blip");
2196:       if (b.moveSwapIndex === null) {
2197:         b.moveSwapIndex = b.moveCursor;
