2214:     return;
2215:   }
2216: 
2217:   if (b.menuState === "BAG_MENU") {
2218:     const totalRows = state.bag.length + 1; // +1 for CANCEL
2219:     if (input === "UP") {
2220:       b.bagCursor = Math.max(0, b.bagCursor - 1);
