2818: function renderKantoTownMap() {
2819:   const canvas = document.getElementById("kanto-town-map-canvas");
2820:   if (!canvas) return;
2821:   const ctx = canvas.getContext("2d");
2822:   const W = canvas.width;
2823:   const H = canvas.height;
2824:   const cellW = W / 16;
2825:   const cellH = H / 16;
2826: 
2827:   ctx.fillStyle = "#162436";
2828:   ctx.fillRect(0, 0, W, H);
2829: 
2830:   // Subtle grid
2831:   ctx.strokeStyle = "rgba(148, 163, 184, 0.14)";
2832:   ctx.lineWidth = 1;
2833:   for (let i = 0; i <= 16; i++) {
2834:     ctx.beginPath();
2835:     ctx.moveTo(i * cellW, 0);
2836:     ctx.lineTo(i * cellW, H);
2837:     ctx.stroke();
2838:     ctx.beginPath();
2839:     ctx.moveTo(0, i * cellH);
2840:     ctx.lineTo(W, i * cellH);
2841:     ctx.stroke();
2842:   }
2843: 
2844:   // Group zones by (townMapX, townMapY)
2845:   const coordMap = {};
2846:   for (const z of engine.canonicalZones) {
2847:     const key = `${z.townMapX},${z.townMapY}`;
2848:     if (!coordMap[key]) coordMap[key] = [];
2849:     coordMap[key].push(z);
2850:   }
2851: 
2852:   for (const [key, zonesAtPoint] of Object.entries(coordMap)) {
2853:     const [gx, gy] = key.split(",").map(Number);
2854:     const hasTown = zonesAtPoint.some((z) => z.category === "town");
2855:     const hasDungeon = zonesAtPoint.some((z) => z.category === "dungeon");
2856:     const px = gx * cellW;
2857:     const py = gy * cellH;
2858: 
2859:     if (hasTown) {
2860:       ctx.fillStyle = "#f59e0b";
2861:       ctx.fillRect(px + 2, py + 2, cellW - 4, cellH - 4);
2862:     } else if (hasDungeon) {
2863:       ctx.fillStyle = "#a855f7";
2864:       ctx.fillRect(px + 3, py + 3, cellW - 6, cellH - 6);
2865:     } else {
2866:       ctx.fillStyle = "#22c55e";
2867:       ctx.fillRect(px + 4, py + 4, cellW - 8, cellH - 8);
2868:     }
2869:   }
2870: 
2871:   // Highlight active zone's Kanto Town Map coordinate
2872:   const cur = state.currentZone;
2873:   const cx = cur.townMapX * cellW;
2874:   const cy = cur.townMapY * cellH;
2875:   ctx.strokeStyle = "#ffffff";
2876:   ctx.lineWidth = 2;
2877:   ctx.strokeRect(cx + 1, cy + 1, cellW - 2, cellH - 2);
2878: }
