import("./src/data/pokeyellow-data.js").then(async ({ POKEYELLOW_DATA }) => {
  const { PokeYellowEngine } = await import("./src/engine.js");
  const engine = new PokeYellowEngine(POKEYELLOW_DATA);
  console.log("Total zones:", engine.allZones.length, "Canonical:", engine.canonicalZones.length);

  let issues = [];
  for (const z of engine.allZones) {
    const ts = engine.tilesetsByConst[z.tileset];
    if (!ts) issues.push(`Zone ${z.constName} missing tileset ${z.tileset}`);
    const bst = ts && engine.bstData[ts.bstKey];
    if (!bst) issues.push(`Zone ${z.constName} missing bst ${ts?.bstKey}`);
    const sheet = ts && engine.gfxSheets[ts.gfxKey];
    if (!sheet) issues.push(`Zone ${z.constName} missing gfx ${ts?.gfxKey}`);

    if (z.blockBytes.length !== z.width * z.height) {
      issues.push(`Zone ${z.constName} blockBytes length ${z.blockBytes.length} != ${z.width * z.height}`);
    }
    for (let i = 0; i < z.blockBytes.length; i++) {
      const bId = z.blockBytes[i];
      if (bId * 16 + 15 >= bst.length) {
        issues.push(`Zone ${z.constName} blockId ${bId} out of bst range (${bst.length})`);
        break;
      }
    }
    // Check connections
    for (const [dir, conn] of Object.entries(z.connections || {})) {
      if (conn && !engine.zonesByConst[conn.targetConst]) {
        issues.push(`Zone ${z.constName} conn ${dir} -> missing ${conn.targetConst}`);
      }
    }
    // Check warps
    for (const w of z.warps || []) {
      if (w.destConst !== "LAST_MAP" && w.destConst !== "EDGES" && !engine.zonesByConst[w.destConst]) {
        issues.push(`Zone ${z.constName} warp -> missing ${w.destConst}`);
      }
    }
    // Check objects
    for (const o of z.objects || []) {
      const sk = engine.spriteConstToKey[o.sprite];
      if (!sk || !engine.spriteSheets[sk]) {
        issues.push(`Zone ${z.constName} object ${o.name} missing sprite ${o.sprite} -> ${sk}`);
      }
      if (o.battle && o.battle.party) {
        for (const [lv, sp] of o.battle.party) {
          if (!POKEYELLOW_DATA.battle.pokemonStats[sp]) {
            issues.push(`Zone ${z.constName} trainer ${o.name} missing mon ${sp}`);
          }
          if (!engine.pokemonSprites[sp]) {
            issues.push(`Zone ${z.constName} trainer ${o.name} missing mon sprite ${sp}`);
          }
        }
      }
    }
    // Check wild
    for (const [lv, sp] of [...(z.wild?.grass || []), ...(z.wild?.water || [])]) {
      if (!POKEYELLOW_DATA.battle.pokemonStats[sp]) {
        issues.push(`Zone ${z.constName} wild missing mon ${sp}`);
      }
      if (!engine.pokemonSprites[sp]) {
        issues.push(`Zone ${z.constName} wild missing mon sprite ${sp}`);
      }
    }
  }
  console.log("Audit issues found:", issues.length);
  for (const iss of issues.slice(0, 50)) console.log(" -", iss);
});
'

