482:     }
483:     return { x: w.x, y: w.y, dir: "DOWN" };
484:   }
485: 
486:   // Otherwise find nearest passable tile to center
487:   const cx = Math.floor(zone.width);
488:   const cy = Math.floor(zone.height);
489:   const ts = engine.tilesetsByConst[zone.tileset];
490:   for (let r = 0; r < Math.max(zone.width, zone.height) * 2; r++) {
491:     for (let dy = -r; dy <= r; dy++) {
