  window.dispatchEvent(new KeyboardEvent("keyup", { code: "ArrowDown" }));
  const blockedByWater = api.state.player.y === 12 && api.state.player.mode === "walk";

  // 2. Test HM03 SURF from shoreline
  const surfResult = api.useFieldMove("SURF");
  const modeAfterSurf = api.state.player.mode;
  const surfSprite = api.state.player.surfSprite;

  // 3. Test HM01 CUT on Vermilion City Gym tree at (15, 18)
  api.loadZone("VERMILION_CITY", { x: 15, y: 17, dir: "DOWN" });
  const tileBeforeCut = api.engine.getCollisionTileAtStep(api.state.currentZone, 15, 18);
  const cutResult = api.useFieldMove("CUT");
  const tileAfterCut = api.engine.getCollisionTileAtStep(api.state.currentZone, 15, 18);

  // 4. Test HM04 STRENGTH & HM05 FLASH
  api.loadZone("ROCK_TUNNEL_1F");
  const flashBefore = api.engine.flashIlluminated;
  api.useFieldMove("FLASH");
  const flashAfter = api.engine.flashIlluminated;

  // 5. Return to Pallet Town shoreline & surf for visual screenshot
  api.loadZone("PALLET_TOWN", { x: 5, y: 12, dir: "DOWN" });
  api.useFieldMove("SURF");

  return {
    blockedByWater,
    surfResult,
    modeAfterSurf,
    surfSprite,
    tileBeforeCut: "0x" + tileBeforeCut.toString(16),
    cutResult,
    tileAfterCut: "0x" + tileAfterCut.toString(16),
    flashBefore,
    flashAfter,
  };
});

await page.waitForTimeout(250);
await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });
console.log("HM Test Results:", JSON.stringify(results, null, 2));
console.log("Errors:", errors);

await browser.close();
server.close();
'

