  ".css": "text/css",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(150);

const check = await page.evaluate(() => {
  const api = window.POKEYELLOW;
  const startBag = api.state.bag.length;
  const startParty = api.state.party.map((m) => m.species);

  // Stream all 220 canonical zones into the single wOverworldMap WRAM buffer
  for (let i = 1; i <= 220; i++) {
    api.loadZone(i);
  }
  api.loadZone("PALLET_TOWN");

  return {
    startBag,
    startParty,
    curMapConst: api.engine.wCurMapConst,
    wramBufferSize: api.engine.wOverworldMap.length,
    palletConnectionsByte: api.state.currentZone.connectionsByte,
  };
});

await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });
console.log("WRAM & Start State Check:", JSON.stringify(check));
console.log("Errors:", errors);

await browser.close();
server.close();
