1840:         ? 20
1841:         : move.id === "DRAGON_RAGE"
1842:         ? 40
1843:         : attacker.level;
1844:     return { damage: fixed, effectiveness: 1.0, crit: false };
1845:   }
1846:   // Gen 1 critical hit rate based on base Speed
1847:   const critChance = Math.min(0.25, (attacker.spd || 50) / 512);
1848:   const crit = Math.random() < critChance;
1849:   const lv = crit ? attacker.level * 2 : attacker.level;
1850: 
1851:   const isSpecial = SPECIAL_TYPES.has(move.type);
1852:   const A = isSpecial ? attacker.spc : attacker.atk;
1853:   const D = Math.max(1, isSpecial ? defender.spc : defender.def);
1854: 
1855:   let baseDmg = Math.floor(
1856:     Math.floor((Math.floor((2 * lv) / 5 + 2) * move.power * A) / D) / 50
1857:   ) + 2;
1858: 
1859:   // STAB (Same-Type Attack Bonus)
1860:   if (attacker.types && attacker.types.includes(move.type)) {
1861:     baseDmg = Math.floor(baseDmg * 1.5);
