function syncBattleTopLevelProps(b) {
  if (!b) return;
  const foe = b.enemyParty[b.activeEnemyIdx] || b.enemyParty[0];
  const pMon =
    b.demoPlayerMon || state.party[b.activePlayerIdx] || state.party[0];
  if (foe) {
    b.species = foe.species;
    b.level = foe.level;
    b.hp = foe.hp;
    b.maxHp = foe.maxHp;
  }
  if (pMon) {
    b.playerHp = pMon.hp;
    b.playerMaxHp = pMon.maxHp;
  }
}

