/* Authentic Game Boy Overlays (Dialogue & Battle) */
.gb-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: transparent;
  padding: 0;
  z-index: 22;
}

/* TextBoxBorder at hlcoord 0, 12 / lb bc, 4, 18 -> Exact bottom 33.33% of 160x144 screen */
.gb-textbox {
  position: relative;
  width: 100%;
  height: 33.33%;
  min-height: 84px;
  background: #fcfaff;
  color: #111827;
  border: 3px double #111827;
  box-shadow: inset 0 0 0 1px #111827;
  border-radius: 0;
  padding: 8px 10px 6px 10px;
  font-family: var(--font-mono);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
}

.gb-textbox-header {
  display: none !important;
}

.gb-textbox-body {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

