.gb-pokedex-menu {
  display: grid;
  grid-template-columns: 1fr 78px;
  width: 100%;
  height: 100%;
  background: #fcfaff;
  color: #111827;
}

.gb-pokedex-left {
  display: flex;
  flex-direction: column;
  padding: 5px 4px 5px 6px;
  border-right: 3px double #111827;
  min-height: 0;
}

.gb-pokedex-title {
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: 0.04em;
  margin-bottom: 3px;
  padding-left: 8px;
}

.gb-pokedex-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.gb-dex-row {
  background: transparent;
  border: none;
  color: #111827;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 900;
  padding: 1px 2px;
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.gb-dex-row.active {
  background: rgba(250, 204, 21, 0.32);
}

.gb-dex-num {
  padding-left: 10px;
  font-size: 9px;
}

.gb-dex-name-line {
  display: flex;
  align-items: center;
  gap: 1px;
  padding-left: 0;
}

.gb-pokedex-right {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 6px 5px;
  font-size: 9.5px;
  font-weight: 900;
}

.gb-pokedex-counts {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-bottom: 2px solid #111827;
  padding-bottom: 6px;
}

.gb-pokedex-count-num {
  text-align: right;
  font-size: 10px;
}

.gb-pokedex-cmds {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.gb-pokedex-cmd-btn {
  background: transparent;
  border: none;
  color: #111827;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 900;
  text-align: left;
  padding: 1px 2px;
  cursor: pointer;
}

.gb-pokedex-cmd-btn:hover {
  background: rgba(250, 204, 21, 0.35);
}

