node -e '
import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";
import http from "http";
import fs from "fs";
import path from "path";

const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(150);

const results = await page.evaluate(() => {
  const api = window.POKEYELLOW;

  // 1. Go to OAKS_LAB before getting starter Pikachu and talk to Rival Blue
  api.loadZone("OAKS_LAB");
  const rival = api.state.npcs.find((n) => n.name === "OAKSLAB_RIVAL");
  api.triggerNpcDialogue(rival);
  const bagAfterTalkingToRival = api.state.bag.length;
  const partyAfterTalkingToRival = api.state.party.length;
  const rivalBattleBtnVisible = !document.getElementById("dialogue-battle-btn")?.classList.contains("hidden");
  const rivalDialogueText = api.state.dialogue?.pages?.[0];
  while (api.state.dialogue) api.interactInFront();
  const battleTriggered = Boolean(api.state.battle);

  // 2. Award starter Pikachu and open START -> POKEDEX to verify Gen I Pokédex UI
  api.awardStarterPikachuInLab();
  api.toggleStartMenu();
  api.handleStartMenuInput("A"); // Open POKEDEX
  // Move cursor to #025 PIKACHU (index 24)
  api.state.startMenu.subCursor = 24;
  api.renderStartMenu();

  return {
    bagAfterTalkingToRival,
    partyAfterTalkingToRival,
    rivalBattleBtnVisible,
    rivalDialogueText,
    battleTriggered,
    dexOpen: api.state.startMenu.subView === "POKEDEX",
