  const partyAfterTalkingToRival = api.state.party.length;
  const rivalBattleBtnVisible = !document.getElementById("dialogue-battle-btn")?.classList.contains("hidden");
  const rivalDialogueText = api.state.dialogue?.pages?.[0];
  while (api.state.dialogue) api.interactInFront();
  const battleTriggered = Boolean(api.state.battle);

  // 2. Award starter Pikachu and open START -> POKEDEX to verify Gen I Pokédex UI
  api.awardStarterPikachuInLab();
  api.toggleStartMenu();
  api.handleStartMenuInput("A"); // Open POKEDEX
  api.state.startMenu.subCursor = 24; // #025 PIKACHU
  api.renderStartMenu();

  return {
    bagAfterTalkingToRival,
    partyAfterTalkingToRival,
    rivalBattleBtnVisible,
    rivalDialogueText,
