  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(150);

const check = await page.evaluate(() => {
  const api = window.POKEYELLOW;

  // Receive Pikachu & encounter Pidgey (#016)
  api.awardStarterPikachuInLab();
  api.triggerWildEncounter([3, "PIDGEY"]);
  api.executeBattleAction("run");

  // Open POKEDEX
  api.toggleStartMenu();
  api.handleStartMenuInput("A");

  // Select #016 PIDGEY (index 15)
  api.state.startMenu.subCursor = 15;
  api.handleStartMenuInput("A"); // Opens right-side 4-item command menu!
  const sideMenuOpen = api.state.startMenu.dexSideMenuOpen;

  // Test 1: DATA (cursor 0)
  api.handleStartMenuInput("A");
  const dataModeOpen = api.state.startMenu.dexModalMode === "DATA";
  api.handleStartMenuInput("B"); // Close DATA back to Pokédex menu

  // Test 2: Move DOWN to CRY (cursor 1) and press A
  api.handleStartMenuInput("DOWN");
  const cursorAtCry = api.state.startMenu.dexCmdCursor === 1;
  api.handleStartMenuInput("A");
  const cryPlayed = api.state.startMenu.dexCryPlaying;

  // Test 3: Move DOWN to AREA (cursor 2) and press A
  api.handleStartMenuInput("DOWN");
  const cursorAtArea = api.state.startMenu.dexCmdCursor === 2;
  api.handleStartMenuInput("A");
  const areaModeOpen = api.state.startMenu.dexModalMode === "AREA";

  return {
    sideMenuOpen,
    dataModeOpen,
    cursorAtCry,
    cryPlayed,
    cursorAtArea,
    areaModeOpen,
  };
});

await page.waitForTimeout(150);
await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });
console.log("4-Selection Pokédex Check:", JSON.stringify(check, null, 2));
console.log("Errors:", errors);

await browser.close();
server.close();
'

