node -e '
import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";
import http from "http";
import fs from "fs";
import path from "path";

const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(150);

const check = await page.evaluate(() => {
  const api = window.POKEYELLOW;
  api.awardStarterPikachuInLab();
  while (api.state.dialogue) api.interactInFront();

  // 1. Pick up BOTH fossils in MT_MOON_B2F
  api.loadZone("MT_MOON_B2F");
  const dome = api.state.npcs.find((n) => n.name === "MTMOONB2F_DOME_FOSSIL");
  const helix = api.state.npcs.find((n) => n.name === "MTMOONB2F_HELIX_FOSSIL");
  api.triggerNpcDialogue(dome);
  while (api.state.dialogue) api.interactInFront();
  const helixStillAvailable = !helix.collected;
  api.triggerNpcDialogue(helix);
  while (api.state.dialogue) api.interactInFront();
  const bagHasBothFossils =
    api.state.bag.some((it) => it.id === "DOME_FOSSIL") &&
    api.state.bag.some((it) => it.id === "HELIX_FOSSIL");

  // 2. Revive BOTH fossils at CINNABAR_LAB_FOSSIL_ROOM
  api.loadZone("CINNABAR_LAB_FOSSIL_ROOM");
  const sci = api.state.npcs.find((n) => n.name.includes("SCIENTIST1"));
  api.triggerNpcDialogue(sci);
  while (api.state.dialogue) api.interactInFront();

  // 3. Obtain BOTH Hitmonlee & Hitmonchan at FIGHTING_DOJO
  api.loadZone("FIGHTING_DOJO");
  const leeBall = api.state.npcs.find((n) => n.name.includes("HITMONLEE"));
  const chanBall = api.state.npcs.find((n) => n.name.includes("HITMONCHAN"));
  api.triggerNpcDialogue(leeBall);
  while (api.state.dialogue) api.interactInFront();
  const chanStillAvailable = !chanBall.collected;
  api.triggerNpcDialogue(chanBall);
  while (api.state.dialogue) api.interactInFront();

  // Open Party Menu to show all 5 in party
  api.toggleStartMenu();
  api.state.startMenu.cursor = 1; // POKEMON
  api.handleStartMenuInput("A");

  return {
    helixStillAvailable,
    bagHasBothFossils,
    chanStillAvailable,
    partySpecies: api.state.party.map((m) => m.species),
    caught: Array.from(api.state.caughtPokemon),
  };
});

await page.waitForTimeout(150);
await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });
console.log("Fossil & Dojo Check:", JSON.stringify(check, null, 2));
console.log("Errors:", errors);

await browser.close();
server.close();
'

