node -e '
import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";
import http from "http";
import fs from "fs";
import path from "path";

const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(150);

// Take screenshot of the Title Screen first
await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });

const check = await page.evaluate(() => {
  const api = window.POKEYELLOW;
  const bootOnTitle = Boolean(api.state.titleMenu?.open && api.state.titleMenu.screen === "TITLE");

  // Press START on Title Screen -> transitions to MAIN_MENU (NEW GAME / OPTION)
  api.handleTitleMenuInput("START");
  const onMainMenu = api.state.titleMenu.screen === "MAIN_MENU";

  // Press A on NEW GAME -> enters Pallet Town overworld!
  api.handleTitleMenuInput("A");
  const titleClosedAfterNewGame = !api.state.titleMenu.open;

  // Open Start Menu before getting Pokédex -> POKEDEX item (idx 0) is hidden (6-item menu)!
  api.toggleStartMenu();
  const pokedexHiddenBeforeDex = document.querySelector("[data-smenu-item=\"0\"]")?.classList.contains("hidden");
  api.toggleStartMenu();

  // Receive Pikachu -> open Start Menu -> POKEDEX item (idx 0) is now visible (7-item menu)!
  api.awardStarterPikachuInLab();
  api.toggleStartMenu();
  const pokedexVisibleAfterPika = !document.querySelector("[data-smenu-item=\"0\"]")?.classList.contains("hidden");

  return {
    bootOnTitle,
    onMainMenu,
    titleClosedAfterNewGame,
    pokedexHiddenBeforeDex,
    pokedexVisibleAfterPika,
  };
});

console.log("Title & Start Menu Check:", JSON.stringify(check, null, 2));
console.log("Errors:", errors);

await browser.close();
server.close();
'
